with cleaned as (select id, store_name, opened_date, case when sqft >= 12628 then 'High' when sqft >= 4435 then 'Medium' else 'Low' end as sqft_level from stores where opened_date >= date '2023-08-24' and region is not distinct from 'Central'), kept as (select s.* from cleaned s where not exists (select 1 from store_sales c where c.store_id = s.id and c.sale_date >= s.opened_date)), scored as (select id, store_name, row_number() over (partition by date_trunc('month', opened_date) order by opened_date desc, id) as event_seq, row_number() over (order by opened_date desc, id) as row_seq from kept where month(opened_date) in (2, 6, 12)), latest_match as (select s.id, s.event_seq, s.row_seq, latest.units from scored s left join lateral (select c.units from store_sales c where c.store_id = s.id order by c.units desc, c.id desc limit 1) latest on true), valid as (select *, floor(row_seq) as row_seq_whole, coalesce(units, 0) as units_filled from latest_match where row_seq > 8) select case when units >= 41 then 'LARGE' else 'SMALL' end as units_tier, case when units_filled >= 60 then 'PREMIUM' else 'STANDARD' end as units_filled_tier, round(avg(units), 2) as avg_units, round(avg(row_seq_whole), 2) as avg_row_seq_whole, sum(event_seq) as total_event_seq from valid group by grouping sets ((case when units >= 41 then 'LARGE' else 'SMALL' end, case when units_filled >= 60 then 'PREMIUM' else 'STANDARD' end), (case when units >= 41 then 'LARGE' else 'SMALL' end), ()) order by total_event_seq desc;
